parameters.Quelltext:
// Eigener Auswahlablauf – EIN CodeBlock bestimmt Testprogramm + Artikelnummer.
// Eingang:  Kennung  = Seriennummer/Artikelnummer des Prüflings (wird vorbelegt)
//           Auftrag  = Auftragsnummer (optional vorbelegt)
// Entscheide frei (if / Regex / Nachschlagen) und rufe am Ende GENAU EINMAL SelectTest(...) auf.
// SelectTest(Testkennung, Version, Auftrag, Pruefparameter):
//   - Version = null  -> aktuell freigegebene Version
//   - eine Artikelnummer gibt es NICHT als eigenes Feld -> über Auftrag und/oder Prüfparameter ("Name=Wert;...") führen
if (Kennung != null && Kennung.StartsWith("AB", System.StringComparison.OrdinalIgnoreCase))
{
    SelectTest("Testprogramm X", "1.0", Auftrag + " / Art 12345", "Artikel=12345");
}
else
{
    SelectTest("Standardprüfung", null, Auftrag, null);
}
return NResult();
